void V25::dmam1_w(uint8_t d)
{
	logerror("%06x: DMAM1 set to %02x\n", PC(), d);
	if ((d & 0x60) == 0)
		logerror("        %s mode, memory to memory, %s\n", BIT(d, 7) ? "Single step" : "Burst", BIT(d, 4) ? "words" : "bytes");
	else if ((d & 0x60) != 0x60)
		logerror("        %s mode, %s to %s, %s\n", BIT(d, 7) ? "Single transfer" : "Demand release",
			BIT(d, 5) ? "I/O" : "memory",
			BIT(d, 6) ? "I/O" : "memory",
			BIT(d, 4) ? "words" : "bytes");
	if (BIT(d, 3))
	{
		uint16_t sar = m_internal_ram[4];
		uint16_t dar = m_internal_ram[5];
		uint16_t sarh_darh = m_internal_ram[6];
		uint16_t tc = m_internal_ram[7];
		logerror("        DMA enabled%s (%04x:%04x -> %04x:%04x, %u %s)\n", BIT(d, 2) ? " and triggered" : "",
			sarh_darh & 0xff00, sar,
			(sarh_darh & 0x00ff) << 8, dar,
			tc, BIT(d, 4) ? "words" : "bytes");
	}
	else
		logerror("        DMA not enabled\n");
	m_dmam[1] = d & 0xfc;
}

uint8_t V25::dic0_r()
{
	return read_irqcontrol(INTD0, m_priority_intd);
}

void V25::dic0_w(uint8_t d)
{
	write_irqcontrol(INTD0, d);
	m_priority_intd = d & 0x7;
}

uint8_t V25::dic1_r()
{
	return read_irqcontrol(INTD1, 7);
}

void V25::dic1_w(uint8_t d)
{
	write_irqcontrol(INTD1, d);
}

uint8_t V25::rfm_r()
{
	return m_RFM;
}

void V25::rfm_w(uint8_t d)
{
	m_RFM = d;
}

uint16_t V25::wtc_r()
{
	return m_WTC;
}

void V25::wtc_w(offs_t a, uint16_t d, uint16_t m)
{
	m_WTC = (m_WTC & ~m) | (d & m);
}

uint8_t V25::flag_r()
{
	return (m_F0 << 3) | (m_F1 << 5);
}

void V25::flag_w(uint8_t d)
{
	m_F0 = BIT(d, 3);
	m_F1 = BIT(d, 5);
}

uint8_t V25::prc_r()
{
	uint8_t ret = m_RAMEN ? 0x40 : 0;

	switch (m_TB)
	{
	case 10:
		break;
	case 13:
		ret |= 0x04;
		break;
	case 16:
		ret |= 0x08;
		break;
	case 20:
		ret |= 0x0C;
		break;
	}

	switch (m_PCK)
	{
	case 2:
		break;
	case 4:
		ret |= 0x01;
		break;
	case 8:
		ret |= 0x02;
		break;
	}

	return ret;
}

void V25::prc_w(uint8_t d)
{
	static const int timebases[4] = { 10, 13, 16, 20 };
	static const int clocks[4] = { 2, 4, 8, 0 };

	logerror("%06x: PRC set to %02x\n", PC(), d);
	m_RAMEN = ((d & 0x40) == 0x40);
	m_TB = timebases[(d & 0x0C) >> 2];
	m_PCK = clocks[d & 0x03];
	if (m_PCK == 0)
	{
		logerror("        Warning: invalid clock divider\n");
		m_PCK = 8;
	}

	unsigned tmp = m_PCK << m_TB;
	attotime time = clocks_to_attotime(tmp);
	m_timers[3]->adjust(time, INTTB, time);
	notify_clock_changed(); // make device_execute_interface pick up the new clocks_to_cycles()

	logerror("        Internal RAM %sabled\n", (m_RAMEN ? "en" : "dis"));
	logerror("        Time base set to 2^%d\n", m_TB);
	logerror("        Clock divider set to %d\n", m_PCK);
}

uint8_t V25::tbic_r()
{
	return read_irqcontrol(INTTB, 7);
}

void V25::tbic_w(uint8_t d)
{
	// time base interrupt doesn't support macro service, bank switching or priority control
	write_irqcontrol(INTTB, d & 0xC0);
}

uint8_t V25::irqs_r()
{
	return m_IRQS;
}

uint8_t V25::ispr_r()
{
	return m_ISPR;
}

uint8_t V25::idb_r()
{
	return m_IDB >> 12;
}

void V25::idb_w(uint8_t d)
{
	m_IDB = (d << 12) | 0xe00;
}

uint8_t V25::v25_read_byte(unsigned a)
{
	if (((a & 0xffe00) == m_IDB && (m_RAMEN || BIT(a, 8))) || a == 0xfffff)
		return m_data.read_byte(a & 0x1ff);
	else
		return m_program->read_byte(a);
}

uint16_t V25::v25_read_word(unsigned a)
{
	if (BIT(a, 0))
		return (v25_read_byte(a) | (v25_read_byte(a + 1) << 8));

	// not sure about this - manual says FFFFC-FFFFE are "reserved"
	if (a == 0xffffe)
		return (m_program->read_byte(a) | (m_data.read_byte(0x1ff) << 8));
	else if ((a & 0xffe00) == m_IDB && (m_RAMEN || BIT(a, 8)))
		return m_data.read_word(a & 0x1ff);
	else
		return m_program->read_word(a);
}

void V25::v25_write_byte(unsigned a, uint8_t d)
{
	if (((a & 0xffe00) == m_IDB && (m_RAMEN || BIT(a, 8))) || a == 0xfffff)
		m_data.write_byte(a & 0x1ff, d);
	else
		m_program->write_byte(a, d);
}

void V25::v25_write_word(unsigned a, uint16_t d)
{
	if (BIT(a, 0))
	{
		v25_write_byte(a, d);
		v25_write_byte(a + 1, d >> 8);
		return;
	}

	// not sure about this - manual says FFFFC-FFFFE are "reserved"
	if (a == 0xffffe)
	{
		m_program->write_byte(a, d);
		m_data.write_byte(0x1ff, d >> 8);
	}
	else if ((a & 0xffe00) == m_IDB && (m_RAMEN || BIT(a, 8)))
		m_data.write_word(a & 0x1ff, d);
	else
		m_program->write_word(a, d);
}


// ---- shims ----

void V25::trace_regs(u16 *r) const
{
	r[0] = Wreg(AW); r[1] = Wreg(CW); r[2] = Wreg(DW); r[3] = Wreg(BW); r[4] = Wreg(SP); r[5] = CompressFlags();
}

V25::V25(sched::Scheduler &s, const char *name, uint32_t clock, const uint8_t *decryption_table)
	: sched::Exec(s, name, clock / 8)
	, m_clock(clock)
	, m_PCK(8)
	, m_prefetch_size(6)
	, m_prefetch_cycles(2)
	, m_chip_type(V25_TYPE)
	, m_has_div_quirk(true)
	, m_v25v35_decryptiontable(decryption_table)
{
}

attotime V25::clocks_to_attotime(uint64_t numclocks) const
{
	const sched::attoseconds_t per_clock = sched::hz_to_attoseconds(m_clock);
	if (numclocks < m_clock)
		return attotime(0, numclocks * per_clock);
	uint32_t remainder;
	const uint32_t quotient = sched::divu_64x32_rem(numclocks, m_clock, remainder);
	return attotime(quotient, uint64_t(remainder) * uint64_t(per_clock));
}

void V25::notify_clock_changed()
{
	set_cycles_per_second(m_clock / m_PCK);
}

void V25::set_input_line(int line, int state)
{
	scheduler().synchronize([this, line, state](s32) { execute_set_input(line, state); });
}

u8 V25::Bus::read_byte(offs_t a) const
{
	auto &f = io ? cpu->io_r : cpu->program_r;
	return f ? f(a & (io ? 0xffff : 0xfffff)) : 0;
}

void V25::Bus::write_byte(offs_t a, u8 d) const
{
	auto &f = io ? cpu->io_w : cpu->program_w;
	if (f) f(a & (io ? 0xffff : 0xfffff), d);
}

// ida_sfr_map: 8-bit registers sit on their byte lane of the 16-bit data
// bus; TM0, MD0, TM1, MD1 and WTC are 16-bit registers
bool V25::sfr_word(offs_t a) const
{
	switch (a & ~1)
	{
		case 0x180: case 0x182: case 0x188: case 0x18a: case 0x1e8: return true;
	}
	return false;
}

bool V25::sfr_read8(offs_t a, u8 &d)
{
	switch (a)
	{
		case 0x100: d = p0_r(); return true;
		case 0x108: d = p1_r(); return true;
		case 0x110: d = p2_r(); return true;
		case 0x138: d = pt_r(); return true;
		case 0x140: d = intm_r(); return true;
		case 0x144: case 0x145: case 0x146: d = ems_r(a - 0x144); return true;
		case 0x14c: d = exic0_r(); return true;
		case 0x14d: d = exic1_r(); return true;
		case 0x14e: d = exic2_r(); return true;
		case 0x160: d = rxb0_r(); return true;
		case 0x165: d = srms0_r(); return true;
		case 0x166: d = stms0_r(); return true;
		case 0x168: d = scm0_r(); return true;
		case 0x169: d = scc0_r(); return true;
		case 0x16a: d = brg0_r(); return true;
		case 0x16b: d = sce0_r(); return true;
		case 0x16c: d = seic0_r(); return true;
		case 0x16d: d = sric0_r(); return true;
		case 0x16e: d = stic0_r(); return true;
		case 0x170: d = rxb1_r(); return true;
		case 0x175: d = srms1_r(); return true;
		case 0x176: d = stms1_r(); return true;
		case 0x178: d = scm1_r(); return true;
		case 0x179: d = scc1_r(); return true;
		case 0x17a: d = brg1_r(); return true;
		case 0x17b: d = sce1_r(); return true;
		case 0x17c: d = seic1_r(); return true;
		case 0x17d: d = sric1_r(); return true;
		case 0x17e: d = stic1_r(); return true;
		case 0x190: d = tmc0_r(); return true;
		case 0x191: d = tmc1_r(); return true;
		case 0x194: case 0x195: case 0x196: d = tmms_r(a - 0x194); return true;
		case 0x19c: d = tmic0_r(); return true;
		case 0x19d: d = tmic1_r(); return true;
		case 0x19e: d = tmic2_r(); return true;
		case 0x1a0: d = dmac0_r(); return true;
		case 0x1a1: d = dmam0_r(); return true;
		case 0x1a2: d = dmac1_r(); return true;
		case 0x1a3: d = dmam1_r(); return true;
		case 0x1ac: d = dic0_r(); return true;
		case 0x1ad: d = dic1_r(); return true;
		case 0x1e1: d = rfm_r(); return true;
		case 0x1ea: d = flag_r(); return true;
		case 0x1eb: d = prc_r(); return true;
		case 0x1ec: d = tbic_r(); return true;
		case 0x1ef: d = irqs_r(); return true;
		case 0x1fc: d = ispr_r(); return true;
		case 0x1ff: d = idb_r(); return true;
	}
	d = 0;
	return false;
}

bool V25::sfr_write8(offs_t a, u8 d)
{
	switch (a)
	{
		case 0x100: p0_w(d); return true;
		case 0x101: pm0_w(d); return true;
		case 0x102: pmc0_w(d); return true;
		case 0x108: p1_w(d); return true;
		case 0x109: pm1_w(d); return true;
		case 0x10a: pmc1_w(d); return true;
		case 0x110: p2_w(d); return true;
		case 0x111: pm2_w(d); return true;
		case 0x112: pmc2_w(d); return true;
		case 0x13b: pmt_w(d); return true;
		case 0x140: intm_w(d); return true;
		case 0x144: case 0x145: case 0x146: ems_w(a - 0x144, d); return true;
		case 0x14c: exic0_w(d); return true;
		case 0x14d: exic1_w(d); return true;
		case 0x14e: exic2_w(d); return true;
		case 0x162: txb0_w(d); return true;
		case 0x165: srms0_w(d); return true;
		case 0x166: stms0_w(d); return true;
		case 0x168: scm0_w(d); return true;
		case 0x169: scc0_w(d); return true;
		case 0x16a: brg0_w(d); return true;
		case 0x16c: seic0_w(d); return true;
		case 0x16d: sric0_w(d); return true;
		case 0x16e: stic0_w(d); return true;
		case 0x172: txb1_w(d); return true;
		case 0x175: srms1_w(d); return true;
		case 0x176: stms1_w(d); return true;
		case 0x178: scm1_w(d); return true;
		case 0x179: scc1_w(d); return true;
		case 0x17a: brg1_w(d); return true;
		case 0x17c: seic1_w(d); return true;
		case 0x17d: sric1_w(d); return true;
		case 0x17e: stic1_w(d); return true;
		case 0x190: tmc0_w(d); return true;
		case 0x191: tmc1_w(d); return true;
		case 0x194: case 0x195: case 0x196: tmms_w(a - 0x194, d); return true;
		case 0x19c: tmic0_w(d); return true;
		case 0x19d: tmic1_w(d); return true;
		case 0x19e: tmic2_w(d); return true;
		case 0x1a0: dmac0_w(d); return true;
		case 0x1a1: dmam0_w(d); return true;
		case 0x1a2: dmac1_w(d); return true;
		case 0x1a3: dmam1_w(d); return true;
		case 0x1ac: dic0_w(d); return true;
		case 0x1ad: dic1_w(d); return true;
		case 0x1e1: rfm_w(d); return true;
		case 0x1ea: flag_w(d); return true;
		case 0x1eb: prc_w(d); return true;
		case 0x1ec: tbic_w(d); return true;
		case 0x1ff: idb_w(d); return true;
	}
	return false;
}

u8 V25::Data::read_byte(offs_t a)
{
	a &= 0x1ff;
	if (a < 0x100)
		return reinterpret_cast<const u8 *>(cpu->m_internal_ram)[a];
	if (cpu->sfr_word(a))
		return u8(read_word(a & ~1) >> ((a & 1) * 8));
	u8 d;
	cpu->sfr_read8(a, d);
	return d;
}

u16 V25::Data::read_word(offs_t a)
{
	a &= 0x1fe;
	if (a < 0x100)
		return cpu->m_internal_ram[a >> 1];
	switch (a)
	{
		case 0x180: return cpu->tm0_r();
		case 0x182: return cpu->md0_r();
		case 0x188: return cpu->tm1_r();
		case 0x18a: return cpu->md1_r();
		case 0x1e8: return cpu->wtc_r();
	}
	u8 lo, hi;
	cpu->sfr_read8(a, lo);
	cpu->sfr_read8(a + 1, hi);
	return lo | (hi << 8);
}

void V25::Data::write_byte(offs_t a, u8 d)
{
	a &= 0x1ff;
	if (a < 0x100)
	{
		reinterpret_cast<u8 *>(cpu->m_internal_ram)[a] = d;
		return;
	}
	if (cpu->sfr_word(a))
	{
		// a byte write to a 16-bit handler: the data on its lane, the other
		// lane zero (the handlers ignore the mask, except WTC's)
		const unsigned sh = (a & 1) * 8;
		const u16 w = u16(d) << sh;
		switch (a & ~1)
		{
			case 0x180: cpu->tm0_w(w); break;
			case 0x182: cpu->md0_w(w); break;
			case 0x188: cpu->tm1_w(w); break;
			case 0x18a: cpu->md1_w(w); break;
			case 0x1e8: cpu->wtc_w(0, w, u16(0xff << sh)); break;
		}
		return;
	}
	cpu->sfr_write8(a, d);
}

void V25::Data::write_word(offs_t a, u16 d)
{
	a &= 0x1fe;
	if (a < 0x100)
	{
		cpu->m_internal_ram[a >> 1] = d;
		return;
	}
	switch (a)
	{
		case 0x180: cpu->tm0_w(d); return;
		case 0x182: cpu->md0_w(d); return;
		case 0x188: cpu->tm1_w(d); return;
		case 0x18a: cpu->md1_w(d); return;
		case 0x1e8: cpu->wtc_w(0, d, 0xffff); return;
	}
	cpu->sfr_write8(a, u8(d));
	cpu->sfr_write8(a + 1, u8(d >> 8));
}

